2629	
2630	interface CourseToolsDraft {
2631	  courseTitle: string;
2632	  courseDescription: string;
2633	  lessonTitle: string;
2634	  lessonReading: string;
2635	}
2636	
2637	type CourseToolsDraftAction =
2638	  | { type: "course.synced"; title: string; description: string }
2639	  | { type: "lesson.synced"; title: string; reading: string }
2640	  | { type: "text.changed"; field: CourseToolsTextField; value: string };
2641	
2642	function courseToolsDraftReducer(
2643	  state: CourseToolsDraft,
2644	  action: CourseToolsDraftAction,
2645	): CourseToolsDraft {
2646	  switch (action.type) {
2647	    case "course.synced":
2648	      return {
2649	        ...state,
2650	        courseTitle: action.title,
2651	        courseDescription: action.description,
2652	      };
2653	    case "lesson.synced":
2654	      return {
2655	        ...state,
2656	        lessonTitle: action.title,
2657	        lessonReading: action.reading,
2658	      };
2659	    case "text.changed":
2660	      return state[action.field] === action.value
2661	        ? state
2662	        : { ...state, [action.field]: action.value };
2663	  }
2664	}
