21	async function courseJson<T>(path: string, init?: RequestInit): Promise<T> {
22	  const response = await fetch(`/api/courses${path}`, {
23	    ...init,
24	    headers: {
25	      ...(init?.body ? { "content-type": "application/json" } : {}),
26	      ...init?.headers,
27	    },
28	  });
29	  return courseResponse<T>(response);
30	}
31	
32	async function courseResponse<T>(response: Response): Promise<T> {
33	  const body = await response.json().catch(() => ({}));
34	  if (!response.ok) {
35	    const message =
36	      body?.statusMessage ??
37	      body?.message ??
38	      body?.error?.message ??
39	      `Course request failed (${response.status})`;
40	    throw new CourseApiError(
41	      message,
42	      response.status,
43	      body?.data?.code,
44	      body?.data?.currentRevision,
45	    );
46	  }
47	  return body as T;
48	}
