141	  );
142	  course.artifacts = course.artifacts.map((artifact) =>
143	    artifact.lessonId && lessonIds.has(artifact.lessonId)
144	      ? (() => {
145	          const { lessonId: _lessonId, ...unlinked } = artifact;
146	          return unlinked;
147	        })()
148	      : artifact,
149	  );
150	  course.materials = course.materials.map((material) =>
151	    material.lessonId && lessonIds.has(material.lessonId)
152	      ? (() => {
153	          const { lessonId: _lessonId, ...unlinked } = material;
154	          return unlinked;
155	        })()
156	      : material,
157	  );
158	  course.assignments = course.assignments.map((assignment) =>
159	    assignment.lessonId && lessonIds.has(assignment.lessonId)
160	      ? (() => {
161	          const { lessonId: _lessonId, ...unlinked } = assignment;
162	          return unlinked;
163	        })()
