199	export function applyCourseOperation(
200	  current: Course,
201	  actorAccountId: string,
202	  operation: CourseOperation,
203	  now = new Date().toISOString(),
204	): Course {
205	  if (operation.courseId !== current.id) {
206	    throw new CourseNotFoundError("The operation targets a different course.");
207	  }
208	  if (
209	    operationNeedsCurrentRevision(operation) &&
210	    operation.baseRevision !== current.revision
211	  ) {
212	    throw new CourseConflictError(
213	      "The course changed while you were editing. Refresh and try again.",
214	      current.revision,
215	    );
216	  }
217	
218	  const actor = memberFor(current, actorAccountId);
219	  const next = structuredClone(current);
220	
221	  switch (operation.type) {
222	    case "course.update": {
223	      if (!roleCanTeach(actor.role)) {
224	        throw new CourseAuthorizationError(
225	          "Only course teachers can change course details.",
226	        );
227	      }
228	      Object.assign(next, operation.patch);
229	      break;
230	    }
231	    case "module.upsert": {
232	      if (!roleCanTeach(actor.role)) {
233	        throw new CourseAuthorizationError(
234	          "Only course teachers can edit modules.",
235	        );
236	      }
237	      const duplicateLesson = operation.module.lessons.find((lesson) =>
238	        next.modules.some(
239	          (module) =>
240	            module.id !== operation.module.id &&
241	            module.lessons.some((item) => item.id === lesson.id),
242	        ),
243	      );
244	      if (duplicateLesson) {
245	        throw new CourseConflictError(
246	          "A lesson with this id already exists in another module.",
247	          next.revision,
248	        );
249	      }
250	      const index = next.modules.findIndex(
251	        (module) => module.id === operation.module.id,
252	      );
253	      if (index === -1) next.modules.push(operation.module);
254	      else {
255	        const retainedIds = new Set(
256	          operation.module.lessons.map((lesson) => lesson.id),
257	        );
258	        const removedIds = new Set(
259	          next.modules[index]!.lessons.map((lesson) => lesson.id).filter(
260	            (id) => !retainedIds.has(id),
261	          ),
262	        );
263	        if (removedIds.size) removeLessonState(next, removedIds);
264	        next.modules[index] = operation.module;
265	      }
266	      appendActivity(
267	        next,
268	        activity(
269	          operation.id,
270	          "module-updated",
271	          actorAccountId,
272	          "Updated the course outline",
273	          now,
274	        ),
275	      );
276	      break;
277	    }
278	    case "module.delete": {
279	      if (!roleCanTeach(actor.role)) {
280	        throw new CourseAuthorizationError(
281	          "Only course teachers can remove modules.",
282	        );
283	      }
284	      const index = next.modules.findIndex(
285	        (module) => module.id === operation.moduleId,
286	      );
287	      if (index === -1)
288	        throw new CourseNotFoundError(
289	          "This module is no longer part of the course.",
290	        );
291	      const lessonIds = new Set(
292	        next.modules[index]!.lessons.map((lesson) => lesson.id),
293	      );
294	      next.modules.splice(index, 1);
295	      removeLessonState(next, lessonIds);
296	      appendActivity(
297	        next,
298	        activity(
299	          operation.id,
300	          "module-removed",
301	          actorAccountId,
302	          "Removed a course module",
303	          now,
304	        ),
305	      );
306	      break;
307	    }
308	    case "lesson.update": {
309	      if (!roleCanTeach(actor.role)) {
310	        throw new CourseAuthorizationError(
311	          "Only course teachers can edit lessons.",
312	        );
313	      }
314	      const module = next.modules.find(
315	        (candidate) => candidate.id === operation.moduleId,
316	      );
317	      if (!module)
318	        throw new CourseNotFoundError(
319	          "This module is no longer part of the course.",
320	        );
321	      if (
322	        next.modules.some(
323	          (candidate) =>
324	            candidate.id !== module.id &&
325	            candidate.lessons.some(
326	              (lesson) => lesson.id === operation.lesson.id,
327	            ),
328	        )
329	      ) {
330	        throw new CourseConflictError(
331	          "A lesson with this id already exists in another module.",
332	          next.revision,
333	        );
334	      }
335	      const index = module.lessons.findIndex(
336	        (lesson) => lesson.id === operation.lesson.id,
337	      );
338	      if (index === -1) module.lessons.push(operation.lesson);
339	      else module.lessons[index] = operation.lesson;
340	      appendActivity(
341	        next,
342	        activity(
343	          operation.id,
344	          "lesson-updated",
345	          actorAccountId,
346	          "Updated a course lesson",
347	          now,
348	          operation.lesson.id,
349	        ),
350	      );
351	      break;
352	    }
353	    case "lesson.delete": {
354	      if (!roleCanTeach(actor.role)) {
355	        throw new CourseAuthorizationError(
356	          "Only course teachers can remove lessons.",
357	        );
358	      }
359	      const module = next.modules.find(
360	        (candidate) => candidate.id === operation.moduleId,
361	      );
362	      if (!module)
363	        throw new CourseNotFoundError(
364	          "This module is no longer part of the course.",
365	        );
366	      const index = module.lessons.findIndex(
367	        (lesson) => lesson.id === operation.lessonId,
