1054	function projectMemberForViewer(
1055	  course: Course,
1056	  viewer: CourseMember,
1057	  member: CourseMember,
1058	): CourseMember {
1059	  if (canSeeMemberPrivateState(viewer, member)) return structuredClone(member);
1060	  return {
1061	    accountId: member.accountId,
1062	    displayName: member.displayName,
1063	    role: member.role,
1064	    teacherAccess: canSeeMemberConsentState(viewer, member)
1065	      ? member.teacherAccess
1066	      : "private",
1067	    // CourseMember remains schema-compatible without revealing member-specific timestamps.
1068	    joinedAt: course.createdAt,
1069	    progress: {
1070	      completedLessonIds: [],
1071	      lastActiveAt: course.createdAt,
1072	    },
1073	  };
