1079	): CourseViewerSnapshot {
1080	  const viewer = memberFor(course, viewerAccountId);
1081	  const projected = structuredClone(course);
1082	  projected.materials = projected.materials.map((material) => {
1083	    const { storageKey: _storageKey, ...publicMaterial } = material;
1084	    return publicMaterial;
