2	import type { CourseRealtimeMessage, CourseViewerSnapshot } from "./contracts";
3	
4	export interface CourseRealtimeState {
5		status: "connected" | "reconnecting" | "offline";
6		presentAccountIds: string[];
7	}
8	
9	export function useCourseRealtime(
10		courseId: string | null,
11		onSnapshot: (snapshot: CourseViewerSnapshot) => void,
12		onCourseUpdated: () => void,
13	): CourseRealtimeState {
14		const [status, setStatus] = useState<CourseRealtimeState["status"]>("offline");
15		const [presentAccountIds, setPresentAccountIds] = useState<string[]>([]);
16		const snapshotRef = useRef(onSnapshot);
17		const updatedRef = useRef(onCourseUpdated);
18		snapshotRef.current = onSnapshot;
19		updatedRef.current = onCourseUpdated;
20	
21		useEffect(() => {
22			if (!courseId) return;
23			let socket: WebSocket | null = null;
24			let retryTimer: number | undefined;
25			let stopped = false;
26			let retries = 0;
27	
28			const connect = () => {
29				if (stopped) return;
30				setStatus(retries === 0 ? "offline" : "reconnecting");
31				const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
32				socket = new WebSocket(`${protocol}//${window.location.host}/api/courses/realtime?courseId=${encodeURIComponent(courseId)}`);
33				socket.addEventListener("open", () => {
34					retries = 0;
35					setStatus("connected");
36				});
37				socket.addEventListener("message", (event) => {
38					if (event.data === "pong") return;
39					try {
40						const message = JSON.parse(String(event.data)) as CourseRealtimeMessage;
41						if (message.type === "snapshot") snapshotRef.current(message.snapshot);
42						if (message.type === "course.updated") updatedRef.current();
43						if (message.type === "presence") setPresentAccountIds(message.accountIds);
44						if (message.type === "gateway.status") setStatus(message.status);
45					} catch {
46						// Ignore non-contract messages from proxies and stale deployments.
47					}
48				});
49				socket.addEventListener("close", () => {
50					if (stopped) return;
51					setStatus("reconnecting");
52					retries += 1;
53					retryTimer = window.setTimeout(connect, Math.min(1_000 * 2 ** retries, 15_000));
54				});
55				socket.addEventListener("error", () => socket?.close());
56			};
57	
58			connect();
59			return () => {
60				stopped = true;
61				if (retryTimer !== undefined) window.clearTimeout(retryTimer);
62				socket?.close();
63			};
64		}, [courseId]);
65	
66		return { status, presentAccountIds };
67	}
