import {
  COURSE_REACTION_EMOJI,
  reactionNames,
  summarizeReactions,
} from "../../courses/course-comments";
import type {
  CourseMember,
  CourseReaction,
  CourseReactionTarget,
} from "../../courses/contracts";

const chipClass = css({
  display: "inline-flex",
  alignItems: "center",
  gap: "0.25rem",
  border: "1px solid color-mix(in srgb, var(--ink) 40%, transparent)",
  bg: "var(--paper)",
