});

const activeChipClass = css({
  borderColor: "var(--course-green-dark, #14743c)",
  bg: "var(--course-wash, #ddebdd)",
  fontWeight: 700,
});

/** Emoji reactions for any course post: a comment, a document, an artifact. */
export function CourseReactionBar({
  reactions,
  members,
  targetKind,
  targetId,
  viewerAccountId,
  onToggle,
  disabled = false,
}: {
  reactions: readonly CourseReaction[];
  members: readonly CourseMember[];
  targetKind: CourseReactionTarget;
  targetId: string;
  viewerAccountId: string;
  onToggle(emoji: string): void;
  disabled?: boolean;
}) {
  const [pickerOpen, setPickerOpen] = useState(false);
  const summaries = summarizeReactions(
    reactions,
    targetKind,
    targetId,
    viewerAccountId,
  );
  const displayName = (accountId: string) =>
    accountId === viewerAccountId
      ? "You"
      : (members.find((member) => member.accountId === accountId)
          ?.displayName ?? "Course member");

  return (
    <div
      className={css({
        display: "flex",
        flexWrap: "wrap",
        alignItems: "center",
        gap: "0.3rem",
      })}
    >
      {summaries.map((summary) => (
        <button
          key={summary.emoji}
          type="button"
          disabled={disabled}
          className={cx(chipClass, summary.reacted && activeChipClass)}
          title={reactionNames(summary, displayName)}
          aria-pressed={summary.reacted}
          onClick={() => onToggle(summary.emoji)}
        >
          <span aria-hidden>{summary.emoji}</span>
          <span className={css({ fontFamily: "var(--mono-display)" })}>
            {summary.count}
          </span>
        </button>
      ))}
      {disabled ? null : pickerOpen ? (
        <span
          className={css({
            display: "inline-flex",
            alignItems: "center",
            gap: "0.15rem",
            border: "1px solid var(--ink)",
            bg: "var(--paper)",
            px: "0.2rem",
            py: "0.1rem",
          })}
        >
          {COURSE_REACTION_EMOJI.map((emoji) => (
            <button
              key={emoji}
              type="button"
              aria-label={`React with ${emoji}`}
              className={css({
                px: "0.2rem",
                py: "0.1rem",
                fontSize: "0.95rem",
                lineHeight: 1.2,
                cursor: "pointer",
                _hover: { bg: "var(--course-wash, #ddebdd)" },
              })}
              onClick={() => {
                onToggle(emoji);
                setPickerOpen(false);
              }}
            >
              {emoji}
            </button>
          ))}
        </span>
      ) : (
        <button
          type="button"
          className={cx(
            chipClass,
            css({ color: "var(--ink-soft)", borderStyle: "dashed" }),
          )}
          aria-label="Add a reaction"
          onClick={() => setPickerOpen(true)}
        >
          <SmilePlus size={13} />
        </button>
      )}
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import {
  BookOpen,
  CreditCard,
  FileText,
  Layers3,
  MessageSquareText,
  Search,
  Shapes,
  Sparkles,
  StickyNote,
  Users,
  BookUp,
} from "lucide-react";
import { css, cx } from "../../../styled-system/css";
import {
  COURSE_SEARCH_KIND_LABEL,
  searchCourse,
  type CourseSearchKind,
  type CourseSearchResult,
} from "../../courses/course-search";
import { allCourseLessons, type Course } from "../../courses/contracts";
import { courseLabelClass } from "./course-ui";

const KIND_ICON: Record<CourseSearchKind, typeof BookOpen> = {
  lesson: BookOpen,
  module: Layers3,
  document: FileText,
  artifact: Shapes,
  assignment: BookUp,
  card: CreditCard,
  comment: MessageSquareText,
  note: StickyNote,
  member: Users,
};

const rowClass = css({
  display: "grid",
  w: "100%",
  gridTemplateColumns: "1.4rem minmax(0, 1fr) auto",
  alignItems: "center",
  gap: "0.6rem",
  borderLeft: "3px solid transparent",
  px: "0.75rem",
  py: "0.55rem",
  textAlign: "left",
  cursor: "pointer",
});

const activeRowClass = css({
  borderLeftColor: "var(--course-green, #1e9b50)",
  bg: "var(--course-wash, #ddebdd)",
});

/**
 * One search box over everything a course holds, plus a hand-off to Keating
 * when the answer is not in the course yet.
 */
export function CourseCommandPalette({
  course,
  onClose,
  onSelect,
  onAskKeating,
}: {
  course: Course;
  onClose(): void;
  onSelect(result: CourseSearchResult): void;
  onAskKeating(query: string): void;
}) {
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const listRef = useRef<HTMLDivElement>(null);

  const results = useMemo(() => {
    const trimmed = query.trim();
    if (trimmed) return searchCourse(course, trimmed, { limit: 24 });
    return allCourseLessons(course)
      .slice(0, 8)
      .map<CourseSearchResult>((lesson) => ({
        key: `lesson:${lesson.id}`,
        kind: "lesson",
        id: lesson.id,
        title: lesson.title,
        detail: lesson.summary || "Open this lesson",
        lessonId: lesson.id,
        score: 0,
      }));
  }, [course, query]);

  const askIndex = results.length;
  const optionCount = results.length + (query.trim() ? 1 : 0);

  useEffect(() => {
    setActive(0);
  }, [query]);

  useEffect(() => {
    listRef.current
      ?.querySelector<HTMLElement>('[data-active="true"]')
      ?.scrollIntoView({ block: "nearest" });
  }, [active, results]);

  const choose = (index: number) => {
    if (index === askIndex && query.trim()) {
      onAskKeating(query.trim());
      return;
    }
    const result = results[index];
    if (result) onSelect(result);
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label="Search this course"
      className={css({
        position: "fixed",
        inset: 0,
        zIndex: 90,
        display: "flex",
        justifyContent: "center",
        bg: "color-mix(in srgb, var(--ink) 45%, transparent)",
        px: "1rem",
        pt: { base: "3rem", md: "6rem" },
      })}
      onClick={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div
        className={css({
          display: "flex",
          w: "100%",
          maxW: "40rem",
          maxH: "70vh",
          flexDir: "column",
          border: "2px solid var(--ink)",
          bg: "var(--card)",
          boxShadow: "8px 8px 0 color-mix(in srgb, var(--ink) 35%, transparent)",
        })}
      >
        <div
          className={css({
            display: "flex",
            alignItems: "center",
            gap: "0.6rem",
            borderBottom: "2px solid var(--ink)",
            px: "0.85rem",
            py: "0.7rem",
          })}
        >
          <Search size={17} />
          {/* eslint-disable-next-line jsx-a11y/no-autofocus */}
          <input
            autoFocus
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Escape") {
                event.preventDefault();
                onClose();
              } else if (event.key === "ArrowDown") {
                event.preventDefault();
                setActive((index) => (index + 1) % Math.max(optionCount, 1));
              } else if (event.key === "ArrowUp") {
                event.preventDefault();
                setActive(
                  (index) =>
                    (index - 1 + Math.max(optionCount, 1)) %
                    Math.max(optionCount, 1),
                );
              } else if (event.key === "Enter") {
                event.preventDefault();
                choose(active);
              }
            }}
            placeholder="Search lessons, documents, artifacts, discussion…"
            aria-label="Search this course"
            className={css({
              w: "100%",
              bg: "transparent",
              fontSize: "0.95rem",
              color: "var(--ink)",
              outline: 0,
            })}
          />
          <kbd
            className={css({
              display: { base: "none", sm: "inline-block" },
              border: "1px solid color-mix(in srgb, var(--ink) 40%, transparent)",
              px: "0.35rem",
              fontFamily: "var(--mono-display)",
              fontSize: "0.6rem",
              color: "var(--ink-soft)",
            })}
          >
            ESC
          </kbd>
        </div>
        <div ref={listRef} className={css({ overflowY: "auto" })}>
          <p className={cx(courseLabelClass, css({ px: "0.85rem", pt: "0.7rem" }))}>
            {query.trim()
              ? `${results.length} result${results.length === 1 ? "" : "s"}`
              : "Jump to a lesson"}
          </p>
          <div className={css({ mt: "0.4rem", pb: "0.5rem" })}>
            {results.map((result, index) => {
              const Icon = KIND_ICON[result.kind];
              return (
                <button
                  key={result.key}
                  type="button"
                  data-active={index === active}
                  className={cx(rowClass, index === active && activeRowClass)}
                  onMouseEnter={() => setActive(index)}
                  onClick={() => choose(index)}
                >
                  <Icon size={15} />
                  <span className={css({ minW: 0 })}>
                    <strong
                      className={css({
                        display: "block",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                        fontSize: "0.85rem",
                      })}
                    >
                      {result.title}
                    </strong>
                    <small
                      className={css({
                        display: "block",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                        color: "var(--ink-soft)",
                      })}
                    >
                      {result.detail}
                    </small>
                  </span>
                  <span
                    className={css({
                      fontFamily: "var(--mono-display)",
                      fontSize: "0.58rem",
                      textTransform: "uppercase",
                      color: "var(--ink-soft)",
                    })}
                  >
                    {COURSE_SEARCH_KIND_LABEL[result.kind]}
                  </span>
                </button>
              );
            })}
            {query.trim() ? (
              <button
                type="button"
                data-active={active === askIndex}
                className={cx(rowClass, active === askIndex && activeRowClass)}
                onMouseEnter={() => setActive(askIndex)}
                onClick={() => choose(askIndex)}
              >
                <Sparkles size={15} />
                <span className={css({ minW: 0 })}>
                  <strong
                    className={css({ display: "block", fontSize: "0.85rem" })}
                  >
                    Ask Keating to search for “{query.trim()}”
                  </strong>
                  <small
                    className={css({ display: "block", color: "var(--ink-soft)" })}
                  >
                    Opens chat with the course loaded and the request ready to send
                  </small>
                </span>
                <span
                  className={css({
                    fontFamily: "var(--mono-display)",
                    fontSize: "0.58rem",
                    textTransform: "uppercase",
                    color: "var(--ink-soft)",
                  })}
                >
                  Keating
                </span>
              </button>
            ) : null}
            {query.trim() && !results.length ? (
              <p
                className={css({
                  px: "0.85rem",
                  py: "0.6rem",
                  fontSize: "0.78rem",
                  color: "var(--ink-soft)",
                })}
              >
                Nothing in this course matches yet.
              </p>
            ) : null}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { Link } from "@tanstack/react-router";
import {
  BookOpen,
  Check,
  ChevronDown,
  LibraryBig,
  Plus,
  RefreshCw,
} from "lucide-react";
import { css, cx } from "../../../styled-system/css";
import { listCourses } from "../../courses/client";
import type { CourseListItem } from "../../courses/contracts";
import { courseLabelClass } from "./course-ui";

const itemClass = css({
  display: "grid",
  w: "100%",
  gridTemplateColumns: "1rem minmax(0, 1fr)",
  alignItems: "center",
  gap: "0.5rem",
  px: "0.7rem",
  py: "0.5rem",
  color: "inherit",
  textAlign: "left",
  textDecoration: "none",
  _hover: { bg: "var(--course-wash, #ddebdd)" },
});

/** Move between course workspaces without going back to the library first. */
export function CourseSwitcher({
  courseId,
  title,
  role,
}: {
  courseId: string;
  title: string;
  role: string;
}) {
  const [open, setOpen] = useState(false);
  const [courses, setCourses] = useState<CourseListItem[]>([]);
  const [state, setState] = useState<"idle" | "loading" | "error">("idle");
  const [filter, setFilter] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open || state !== "idle" || courses.length) return;
    setState("loading");
    listCourses()
      .then((items) => {
        setCourses(items);
        setState("idle");
      })
      .catch(() => setState("error"));
  }, [courses.length, open, state]);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: MouseEvent) => {
      if (!containerRef.current?.contains(event.target as Node)) setOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  const needle = filter.trim().toLowerCase();
  const visible = needle
    ? courses.filter((course) => course.title.toLowerCase().includes(needle))
    : courses;

  return (
    <div ref={containerRef} className={css({ position: "relative", minW: 0 })}>
      <button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen((value) => !value)}
        className={css({
          display: "flex",
          minW: 0,
          alignItems: "center",
          gap: "0.5rem",
          px: "0.35rem",
          py: "0.15rem",
          textAlign: "left",
          cursor: "pointer",
          _hover: { bg: "var(--course-wash, #ddebdd)" },
        })}
      >
        <span className={css({ minW: 0 })}>
          <span className={cx(courseLabelClass, css({ display: "block" }))}>
            Course workspace · {role}
          </span>
          <span
            className={css({
              display: "block",
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
              fontFamily: "Georgia, serif",
              fontSize: "1.1rem",
              fontWeight: 700,
              lineHeight: 1.2,
            })}
          >
            {title}
          </span>
        </span>
        <ChevronDown size={16} />
      </button>
      {open ? (
        <div
          role="menu"
          className={css({
            position: "absolute",
            top: "calc(100% + 0.4rem)",
            left: 0,
            zIndex: 60,
            w: "min(22rem, calc(100vw - 2rem))",
            border: "2px solid var(--ink)",
            bg: "var(--card)",
            boxShadow: "6px 6px 0 color-mix(in srgb, var(--ink) 30%, transparent)",
          })}
        >
          <div
            className={css({
              borderBottom: "1px solid var(--ink)",
              p: "0.5rem",
            })}
          >
            <input
              value={filter}
              onChange={(event) => setFilter(event.target.value)}
              placeholder="Find a course…"
              aria-label="Find a course"
              className={css({
                w: "100%",
                border: "1px solid var(--ink)",
                bg: "var(--paper)",
                px: "0.5rem",
                py: "0.4rem",
                fontSize: "0.8rem",
                outline: 0,
              })}
            />
          </div>
          <div className={css({ maxH: "17rem", overflowY: "auto" })}>
            {state === "loading" ? (
              <p
                className={css({
                  display: "flex",
                  alignItems: "center",
                  gap: "0.4rem",
                  px: "0.7rem",
                  py: "0.6rem",
                  fontSize: "0.78rem",
                  color: "var(--ink-soft)",
                })}
              >
                <RefreshCw size={13} /> Loading your courses…
              </p>
            ) : state === "error" ? (
              <p
                className={css({
                  px: "0.7rem",
                  py: "0.6rem",
                  fontSize: "0.78rem",
                  color: "var(--destructive)",
                })}
              >
                Your other courses could not be loaded.
              </p>
            ) : visible.length ? (
              visible.map((course) => (
                <Link
                  key={course.id}
                  to="/courses/$courseId"
                  params={{ courseId: course.id }}
                  className={itemClass}
                  onClick={() => setOpen(false)}
                >
                  {course.id === courseId ? (
                    <Check size={14} />
                  ) : (
                    <BookOpen size={14} />
                  )}
                  <span className={css({ minW: 0 })}>
                    <strong
                      className={css({
                        display: "block",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                        fontSize: "0.83rem",
                      })}
                    >
                      {course.title}
                    </strong>
                    <small className={css({ color: "var(--ink-soft)" })}>
                      {course.lessonCount} lessons · {course.completedLessons} done
                      · {course.role}
                    </small>
                  </span>
                </Link>
              ))
            ) : (
              <p
                className={css({
                  px: "0.7rem",
                  py: "0.6rem",
                  fontSize: "0.78rem",
                  color: "var(--ink-soft)",
                })}
              >
                No other course matches.
              </p>
            )}
          </div>
          <div className={css({ borderTop: "1px solid var(--ink)" })}>
            <Link
              to="/courses"
              className={itemClass}
              onClick={() => setOpen(false)}
            >
              <LibraryBig size={14} />
              <span className={css({ fontSize: "0.82rem", fontWeight: 700 })}>
                Course library
              </span>
            </Link>
            <Link
              to="/chat"
              search={{ courseMode: "create" }}
              className={itemClass}
              onClick={() => setOpen(false)}
            >
              <Plus size={14} />
              <span className={css({ fontSize: "0.82rem", fontWeight: 700 })}>
                Plan a new course with Keating
              </span>
            </Link>
          </div>
        </div>
      ) : null}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import {
  BookUp,
  ChevronDown,
  CreditCard,
  FileQuestion,
  FilePlus2,
  Layers3,
  Link2,
  Plus,
  RefreshCw,
  Shapes,
  Upload,
} from "lucide-react";
import { css, cx } from "../../../styled-system/css";
import {
  newCourseOperationId,
  uploadCourseMaterial,
  type applyCourseOperation,
} from "../../courses/client";
import type { CourseViewerSnapshot } from "../../courses/contracts";
import type { CourseBuilderSection } from "./CourseBuilder";
import {
  courseButtonClass,
  courseInputClass,
  courseLabelClass,
  coursePrimaryButtonClass,
} from "./course-ui";

type Mutate = (
  operation: Parameters<typeof applyCourseOperation>[0],
  label: string,
) => Promise<void>;

const menuItemClass = css({
  display: "grid",
  w: "100%",
  gridTemplateColumns: "1rem minmax(0, 1fr)",
  alignItems: "center",
  gap: "0.55rem",
  px: "0.7rem",
  py: "0.55rem",
  textAlign: "left",
  cursor: "pointer",
  _hover: { bg: "var(--course-wash, #ddebdd)" },
});

/**
 * Pick a file and attach it to the course (or the open lesson) in one click.
 * Uploads bypass the operation log because bytes are stored beside the course.
 */
export function CourseDocumentUploadButton({
  courseId,
  lessonId,
  onSnapshot,
  onError,
  label = "Add document",
  className,
}: {
  courseId: string;
  lessonId?: string;
  onSnapshot(snapshot: CourseViewerSnapshot): void;
  onError(message: string): void;
  label?: string;
  className?: string;
}) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  return (
    <>
      <input
        ref={inputRef}
        type="file"
        className={css({ display: "none" })}
        onChange={(event) => {
          const file = event.target.files?.[0];
          event.target.value = "";
          if (!file) return;
          setBusy(true);
          void uploadCourseMaterial(courseId, file, {
            title: file.name,
            ...(lessonId ? { lessonId } : {}),
          })
            .then(onSnapshot)
            .catch((cause) =>
              onError(
                cause instanceof Error
                  ? cause.message
                  : "That document could not be uploaded.",
              ),
            )
            .finally(() => setBusy(false));
        }}
      />
      <button
        type="button"
        disabled={busy}
        className={cx(courseButtonClass, className)}
        onClick={() => inputRef.current?.click()}
      >
        {busy ? <RefreshCw size={14} /> : <FilePlus2 size={14} />}
        {busy ? "Uploading…" : label}
      </button>
    </>
  );
}

/** Everything a course can gain, one menu, always in the same place. */
export function CourseAddMenu({
  snapshot,
  activeLessonId,
  saving,
  mutate,
  onSnapshot,
  onError,
  onOpenBuilder,
}: {
  snapshot: CourseViewerSnapshot;
  activeLessonId?: string;
  saving: string;
  mutate: Mutate;
  onSnapshot(snapshot: CourseViewerSnapshot): void;
  onError(message: string): void;
  onOpenBuilder(section: CourseBuilderSection): void;
}) {
  const [open, setOpen] = useState(false);
  const [linkOpen, setLinkOpen] = useState(false);
  const [linkTitle, setLinkTitle] = useState("");
  const [linkUrl, setLinkUrl] = useState("");
  const [uploading, setUploading] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const canEdit = snapshot.permissions.canEditCourse;
  const canCards = snapshot.permissions.canEditDeck;

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: MouseEvent) => {
      if (!containerRef.current?.contains(event.target as Node)) {
        setOpen(false);
        setLinkOpen(false);
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
        setLinkOpen(false);
      }
    };
    document.addEventListener("mousedown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("mousedown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [open]);

  if (!canEdit && !canCards) return null;

  const go = (section: CourseBuilderSection) => {
    setOpen(false);
    onOpenBuilder(section);
  };

  const addLink = async () => {
    if (!linkTitle.trim() || !linkUrl.trim()) return;
    await mutate(
      {
        id: newCourseOperationId(),
        courseId: snapshot.course.id,
        baseRevision: snapshot.course.revision,
        type: "material.add",
        material: {
          id: `material_${crypto.randomUUID().replaceAll("-", "")}`,
          kind: "link",
          title: linkTitle.trim(),
          url: linkUrl.trim(),
          ...(activeLessonId ? { lessonId: activeLessonId } : {}),
        },
      },
      "material-link",
    );
    setLinkTitle("");
    setLinkUrl("");
    setLinkOpen(false);
    setOpen(false);
  };

  return (
    <div ref={containerRef} className={css({ position: "relative" })}>
      <input
        ref={fileRef}
        type="file"
        className={css({ display: "none" })}
        onChange={(event) => {
          const file = event.target.files?.[0];
          event.target.value = "";
          if (!file) return;
          setUploading(true);
          setOpen(false);
          void uploadCourseMaterial(snapshot.course.id, file, {
            title: file.name,
            ...(activeLessonId ? { lessonId: activeLessonId } : {}),
          })
            .then(onSnapshot)
            .catch((cause) =>
              onError(
                cause instanceof Error
                  ? cause.message
                  : "That document could not be uploaded.",
              ),
            )
            .finally(() => setUploading(false));
        }}
      />
      <button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        disabled={uploading}
        className={cx(courseButtonClass, coursePrimaryButtonClass)}
        onClick={() => setOpen((value) => !value)}
      >
        {uploading ? <RefreshCw size={14} /> : <Plus size={14} />}
        <span className={css({ display: { base: "none", sm: "inline" } })}>
          {uploading ? "Uploading…" : "Add"}
        </span>
        <ChevronDown size={13} />
      </button>
      {open ? (
        <div
          role="menu"
          className={css({
            position: "absolute",
            top: "calc(100% + 0.4rem)",
            right: 0,
            zIndex: 60,
            w: "min(20rem, calc(100vw - 2rem))",
            border: "2px solid var(--ink)",
            bg: "var(--card)",
            boxShadow: "6px 6px 0 color-mix(in srgb, var(--ink) 30%, transparent)",
          })}
