                  >
                    <Plus size={13} /> Add link
                  </button>
                </div>
              ) : null}
              <button
                type="button"
                className={menuItemClass}
                onClick={() => go("outline")}
              >
                <Layers3 size={14} />
                <span className={css({ fontSize: "0.82rem", fontWeight: 700 })}>
                  Module or lesson
                </span>
              </button>
              <button
                type="button"
                className={menuItemClass}
                onClick={() => go("assignments")}
              >
                <BookUp size={14} />
                <span className={css({ fontSize: "0.82rem", fontWeight: 700 })}>
                  Assignment
                </span>
              </button>
              <button
                type="button"
                className={menuItemClass}
                onClick={() => go("artifacts")}
              >
                <FileQuestion size={14} />
                <span className={css({ fontSize: "0.82rem", fontWeight: 700 })}>
                  Quiz or artifact
                </span>
              </button>
            </>
          ) : null}
          {canCards ? (
            <button
              type="button"
              className={menuItemClass}
              onClick={() => go("cards")}
            >
              <CreditCard size={14} />
              <span className={css({ fontSize: "0.82rem", fontWeight: 700 })}>
                Flashcard
              </span>
            </button>
          ) : null}
          {canEdit ? (
            <button
              type="button"
              className={cx(
                menuItemClass,
                css({ borderTop: "1px solid var(--ink)" }),
              )}
              onClick={() => go("documents")}
            >
              <Shapes size={14} />
              <span className={css({ fontSize: "0.82rem", fontWeight: 700 })}>
                Open the full builder
              </span>
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

