function CommentCard({
  snapshot,
  comment,
  saving,
  mutate,
  canPost,
  isReply,
  lessonTitle,
  onReply,
  onOpenLesson,
}: {
  snapshot: CourseViewerSnapshot;
  comment: CourseComment;
  saving: string;
  mutate: Mutate;
  canPost: boolean;
  isReply: boolean;
  lessonTitle?: string;
  onReply?: () => void;
  onOpenLesson?: () => void;
}) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(comment.body);
  useEffect(() => setDraft(comment.body), [comment.body]);
  const author = snapshot.course.members.find(
    (member) => member.accountId === comment.accountId,
  );
  const mine = comment.accountId === snapshot.viewer.accountId;
  const canDelete = mine || snapshot.permissions.canReview;

  const base = () => ({
    id: newCourseOperationId(),
    courseId: snapshot.course.id,
    baseRevision: snapshot.course.revision,
  });

  return (
    <article
      className={css({
        borderLeft: "3px solid var(--peer-blue, #3468b3)",
        bg: "var(--paper)",
        px: "0.75rem",
        py: "0.6rem",
      })}
      style={isReply ? { borderLeftColor: "color-mix(in srgb, var(--ink) 35%, transparent)" } : undefined}
    >
      <div
        className={css({
          display: "flex",
          alignItems: "center",
          gap: "0.5rem",
        })}
      >
        <Avatar
          name={author?.displayName ?? "?"}
          role={author?.role ?? "peer"}
        />
        <span className={css({ minW: 0, flex: 1 })}>
          <strong className={css({ fontSize: "0.8rem" })}>
            {mine ? "You" : (author?.displayName ?? "Course member")}
          </strong>
          <small
            className={css({
              ml: "0.4rem",
              fontSize: "0.68rem",
              color: "var(--ink-soft)",
            })}
          >
            {formatCourseRelative(comment.createdAt)}
            {comment.editedAt ? " · edited" : ""}
          </small>
        </span>
        {lessonTitle && onOpenLesson ? (
          <button
            type="button"
            onClick={onOpenLesson}
            className={css({
              border: "1px solid color-mix(in srgb, var(--ink) 30%, transparent)",
              px: "0.35rem",
              fontSize: "0.63rem",
              color: "var(--ink-soft)",
              cursor: "pointer",
              _hover: { color: "var(--ink)" },
            })}
          >
            {lessonTitle}
          </button>
        ) : null}
      </div>
      {editing ? (
        <div className={css({ mt: "0.5rem", display: "grid", gap: "0.4rem" })}>
          <textarea
            value={draft}
            rows={3}
            onChange={(event) => setDraft(event.target.value)}
            className={courseInputClass}
            aria-label="Edit comment"
          />
          <div className={css({ display: "flex", gap: "0.35rem", justifyContent: "flex-end" })}>
            <button
              type="button"
              className={courseButtonClass}
              onClick={() => {
                setDraft(comment.body);
                setEditing(false);
              }}
            >
              Cancel
            </button>
            <button
              type="button"
              className={cx(courseButtonClass, coursePrimaryButtonClass)}
              disabled={!draft.trim() || saving === `comment-edit-${comment.id}`}
              onClick={() =>
                void mutate(
                  {
                    ...base(),
                    type: "comment.update",
                    commentId: comment.id,
                    body: draft.trim(),
                  },
                  `comment-edit-${comment.id}`,
                ).then(() => setEditing(false))
              }
            >
              Save
            </button>
          </div>
        </div>
      ) : (
        <p
          className={css({
            mt: "0.4rem",
            whiteSpace: "pre-wrap",
            fontSize: "0.88rem",
            lineHeight: 1.55,
          })}
        >
          {comment.body}
        </p>
      )}
      <div
        className={css({
          mt: "0.5rem",
          display: "flex",
          flexWrap: "wrap",
          alignItems: "center",
          justifyContent: "space-between",
          gap: "0.5rem",
        })}
      >
        <CourseReactionBar
          reactions={snapshot.course.reactions}
          members={snapshot.course.members}
          targetKind="comment"
          targetId={comment.id}
          viewerAccountId={snapshot.viewer.accountId}
          disabled={!canPost}
          onToggle={(emoji) =>
            void mutate(
              {
                ...base(),
                type: "reaction.toggle",
                targetKind: "comment",
                targetId: comment.id,
                emoji,
              },
              `reaction-${comment.id}-${emoji}`,
            )
          }
        />
        <span className={css({ display: "flex", gap: "0.25rem" })}>
          {onReply && canPost ? (
            <button type="button" className={courseButtonClass} onClick={onReply}>
              <CornerDownRight size={12} /> Reply
            </button>
          ) : null}
          {mine && !editing ? (
            <button
              type="button"
              className={courseButtonClass}
              aria-label="Edit comment"
              onClick={() => setEditing(true)}
            >
              <Pencil size={12} />
            </button>
          ) : null}
          {canDelete ? (
            <button
              type="button"
              className={cx(courseButtonClass, css({ color: "var(--destructive)" }))}
              aria-label="Delete comment"
              disabled={saving === `comment-delete-${comment.id}`}
              onClick={() => {
                if (
                  typeof window !== "undefined" &&
                  !window.confirm(
                    isReply
                      ? "Remove this reply?"
                      : "Remove this comment and its replies?",
                  )
                )
                  return;
                void mutate(
                  { ...base(), type: "comment.delete", commentId: comment.id },
                  `comment-delete-${comment.id}`,
                );
              }}
            >
              <Trash2 size={12} />
            </button>
          ) : null}
        </span>
      </div>
    </article>
  );
}

/**
 * Threaded course discussion: one channel per lesson plus a course-wide room,
 * with replies, edits, removals, and reactions on every post.
 */
export function CourseDiscussion({
  snapshot,
  activeLesson,
  saving,
  mutate,
  onSelectLesson,
}: {
  snapshot: CourseViewerSnapshot;
  activeLesson?: CourseLesson;
  saving: string;
  mutate: Mutate;
  onSelectLesson(lessonId: string): void;
}) {
  const [channel, setChannel] = useState<string>(
    activeLesson?.id ?? COURSE_CHANNEL,
  );
  const [draft, setDraft] = useState("");
  const [replyTo, setReplyTo] = useState<string | null>(null);
  const [replyDraft, setReplyDraft] = useState("");
  const [filter, setFilter] = useState("");
  useEffect(() => {
    if (activeLesson) setChannel(activeLesson.id);
  }, [activeLesson?.id]);

  const lessons = useMemo(
    () => snapshot.course.modules.flatMap((module) => module.lessons),
    [snapshot.course.modules],
  );
  const counts = useMemo(
    () => commentCounts(snapshot.course.comments),
    [snapshot.course.comments],
  );
  const scope: CourseDiscussionScope =
    channel === COURSE_CHANNEL
      ? { kind: "course" }
      : channel === ALL_CHANNEL
        ? { kind: "all" }
        : { kind: "lesson", lessonId: channel };
  const threads = useMemo(
    () => buildCommentThreads(snapshot.course.comments, scope, filter),
    [snapshot.course.comments, channel, filter],
  );
  const canPost =
    snapshot.course.settings.allowPeerComments || snapshot.permissions.canReview;
  const postable = channel !== ALL_CHANNEL && canPost;

  const base = () => ({
    id: newCourseOperationId(),
    courseId: snapshot.course.id,
    baseRevision: snapshot.course.revision,
  });

  const post = () => {
    if (!draft.trim() || !postable) return;
    void mutate(
      {
        ...base(),
        type: "comment.add",
        commentId: newCommentId(),
        ...(channel === COURSE_CHANNEL ? {} : { lessonId: channel }),
        body: draft.trim(),
      },
      "comment-add",
    ).then(() => setDraft(""));
  };

  const postReply = (parentId: string) => {
    if (!replyDraft.trim()) return;
    void mutate(
      {
        ...base(),
        type: "comment.add",
        commentId: newCommentId(),
        parentId,
        body: replyDraft.trim(),
      },
      `comment-reply-${parentId}`,
    ).then(() => {
      setReplyDraft("");
      setReplyTo(null);
    });
  };

  return (
    <div className={css({ mx: "auto", maxW: "48rem" })}>
      <div
        className={css({
          display: "flex",
          flexWrap: "wrap",
          alignItems: "end",
          justifyContent: "space-between",
          gap: "0.75rem",
        })}
      >
        <div>
          <p className={courseLabelClass}>Discussion</p>
          <h2
            className={css({
              mt: "0.3rem",
              fontFamily: "Georgia, serif",
              fontSize: { base: "1.9rem", md: "2.4rem" },
              lineHeight: 1.05,
            })}
          >
            Think where others can answer.
          </h2>
        </div>
        <MessageSquareText size={22} />
      </div>

      <div
        className={css({
          mt: "1.1rem",
          display: "grid",
          gap: "0.45rem",
          sm: { gridTemplateColumns: "minmax(0, 1fr) minmax(0, 1fr)" },
        })}
      >
        <label>
          <span className={cx(courseLabelClass, css({ display: "block", mb: "0.2rem" }))}>
            Channel
          </span>
          <select
            value={channel}
            onChange={(event) => {
              const next = event.target.value;
              setChannel(next);
              setReplyTo(null);
              if (next !== COURSE_CHANNEL && next !== ALL_CHANNEL)
                onSelectLesson(next);
            }}
            className={courseInputClass}
          >
            <option value={COURSE_CHANNEL}>
              Course-wide thread ({counts.course ?? 0})
            </option>
            {lessons.map((lesson) => (
              <option key={lesson.id} value={lesson.id}>
                {lesson.title} ({counts[lesson.id] ?? 0})
              </option>
            ))}
            <option value={ALL_CHANNEL}>
              Everything ({snapshot.course.comments.length})
            </option>
          </select>
        </label>
        <label>
          <span className={cx(courseLabelClass, css({ display: "block", mb: "0.2rem" }))}>
            Find in discussion
          </span>
          <span
            className={css({
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
              border: "1px solid var(--ink)",
              bg: "var(--paper)",
              px: "0.55rem",
            })}
          >
            <Search size={14} />
            <input
              value={filter}
              onChange={(event) => setFilter(event.target.value)}
              placeholder="Search threads…"
              aria-label="Search threads"
              className={css({
                w: "100%",
                bg: "transparent",
                py: "0.5rem",
                fontSize: "0.82rem",
                outline: 0,
              })}
            />
          </span>
        </label>
      </div>

      {postable ? (
        <div
          className={css({
            mt: "0.85rem",
            display: "flex",
            alignItems: "stretch",
            gap: "0.45rem",
          })}
        >
          <textarea
            value={draft}
            rows={2}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if ((event.metaKey || event.ctrlKey) && event.key === "Enter")
                post();
            }}
            className={cx(courseInputClass, css({ resize: "vertical" }))}
            placeholder={
              channel === COURSE_CHANNEL
                ? "Ask the whole course…"
                : "Ask or add context for this lesson…"
            }
            aria-label="Write a comment"
          />
          <button
            type="button"
            className={cx(courseButtonClass, coursePrimaryButtonClass)}
            disabled={!draft.trim() || saving === "comment-add"}
            onClick={post}
            aria-label="Post comment"
            title="Post · ⌘↵"
          >
            <Send size={15} />
          </button>
        </div>
      ) : (
        <p className={cx(courseEmptyClass, css({ mt: "0.85rem" }))}>
          {canPost
            ? "Pick a channel to post in. “Everything” is read-only."
            : "Peer comments are turned off for this course."}
        </p>
      )}

      <div className={css({ mt: "1.1rem", display: "grid", gap: "0.7rem" })}>
        {threads.length ? (
          threads.map((thread) => (
            <section key={thread.comment.id}>
              <CommentCard
                snapshot={snapshot}
                comment={thread.comment}
                saving={saving}
                mutate={mutate}
                canPost={canPost}
                isReply={false}
                {...(channel === ALL_CHANNEL && thread.comment.lessonId
                  ? {
                      lessonTitle:
                        lessons.find(
                          (lesson) => lesson.id === thread.comment.lessonId,
                        )?.title ?? "Lesson",
                      onOpenLesson: () =>
                        onSelectLesson(thread.comment.lessonId as string),
                    }
                  : {})}
                onReply={() => {
                  setReplyTo(
                    replyTo === thread.comment.id ? null : thread.comment.id,
                  );
                  setReplyDraft("");
                }}
              />
              {thread.replies.length ? (
                <div
                  className={css({
                    ml: { base: "0.6rem", sm: "1.6rem" },
                    mt: "0.4rem",
                    display: "grid",
                    gap: "0.4rem",
                  })}
                >
                  {thread.replies.map((reply) => (
                    <CommentCard
                      key={reply.id}
                      snapshot={snapshot}
                      comment={reply}
                      saving={saving}
                      mutate={mutate}
                      canPost={canPost}
                      isReply
                    />
                  ))}
                </div>
              ) : null}
              {replyTo === thread.comment.id ? (
                <div
                  className={css({
                    ml: { base: "0.6rem", sm: "1.6rem" },
                    mt: "0.4rem",
                    display: "flex",
                    alignItems: "stretch",
                    gap: "0.4rem",
                  })}
                >
                  <textarea
                    value={replyDraft}
                    rows={2}
                    onChange={(event) => setReplyDraft(event.target.value)}
                    onKeyDown={(event) => {
                      if (
                        (event.metaKey || event.ctrlKey) &&
                        event.key === "Enter"
                      )
                        postReply(thread.comment.id);
                    }}
                    className={cx(courseInputClass, css({ resize: "vertical" }))}
                    placeholder="Reply…"
                    aria-label="Write a reply"
                  />
                  <button
                    type="button"
                    className={cx(courseButtonClass, coursePrimaryButtonClass)}
                    disabled={
                      !replyDraft.trim() ||
                      saving === `comment-reply-${thread.comment.id}`
                    }
                    onClick={() => postReply(thread.comment.id)}
                    aria-label="Post reply"
                  >
                    <Send size={14} />
                  </button>
                  <button
                    type="button"
                    className={courseButtonClass}
                    aria-label="Cancel reply"
                    onClick={() => setReplyTo(null)}
                  >
                    <X size={14} />
                  </button>
                </div>
              ) : null}
            </section>
          ))
        ) : (
          <p className={courseEmptyClass}>
            {filter.trim()
              ? "No thread matches that search."
              : "No thread yet. Leave the first useful question."}
          </p>
        )}
      </div>
    </div>
  );
}

/**
 * Concrete requests a course workspace can hand to Keating. The workspace links
 * into chat with `ask=…`; chat drops the text into the composer so the learner
 * still reads and sends it themselves.
 */

export type CourseAskView = "read" | "discuss" | "review" | "build";

export interface CourseAskAction {
  id: string;
  label: string;
  description: string;
  prompt: string;
}

export interface CourseAskContext {
  courseTitle: string;
  lessonTitle?: string;
  lessonId?: string;
  view: CourseAskView;
}

const MAX_ASK_LENGTH = 2_000;

export function courseAskActions(context: CourseAskContext): CourseAskAction[] {
  const course = `“${context.courseTitle}”`;
  const lesson = context.lessonTitle ? `“${context.lessonTitle}”` : null;
  const lessonRef = context.lessonId ? ` (lesson id \`${context.lessonId}\`)` : "";
  const actions: CourseAskAction[] = [];

  if (lesson && (context.view === "read" || context.view === "build")) {
    actions.push(
      {
        id: "lesson-review",
        label: "Review this lesson",
        description: "Find what is missing, unclear, or out of order",
        prompt: `Inspect ${course} and read the lesson ${lesson}${lessonRef}. Tell me the two weakest parts of it and why, then wait for me to choose before changing anything.`,
      },
      {
        id: "lesson-sources",
        label: "Find sources for it",
        description: "Search for readings worth attaching",
        prompt: `Search for three reliable, current sources that would strengthen the lesson ${lesson}${lessonRef} in ${course}. For each one give the link, what it adds, and where in the lesson it belongs. Ask me before adding anything.`,
      },
      {
        id: "lesson-quiz",
        label: "Draft a quiz",
        description: "Post-lesson questions that test transfer",
        prompt: `Draft a short quiz for the lesson ${lesson}${lessonRef} in ${course} that tests transfer rather than recall. Show me the questions first; add it to the course only once I agree.`,
      },
      {
        id: "lesson-practice",
        label: "Write a practice question",
        description: "One exercise with a rubric",
        prompt: `Write one practice question with a three-point rubric for the lesson ${lesson}${lessonRef} in ${course}. Explain what a wrong answer would reveal, then wait for my go-ahead.`,
      },
    );
  }

  if (context.view === "discuss") {
    actions.push(
      {
        id: "discussion-summary",
        label: "Read the discussion with me",
        description: "Surface the real question underneath",
        prompt: `Look at the discussion in ${course}${lesson ? ` for the lesson ${lesson}` : ""}. What is the question people keep circling? Suggest how the course should answer it.`,
      },
      {
        id: "discussion-followup",
        label: "Suggest a follow-up",
        description: "A prompt that moves the thread forward",
        prompt: `Based on the discussion in ${course}${lesson ? ` on ${lesson}` : ""}, propose one follow-up question I could post that would make people think rather than agree.`,
      },
    );
  }

  if (context.view === "review") {
    actions.push({
      id: "review-help",
      label: "Help me review work",
      description: "Turn a rubric into useful feedback",
      prompt: `Help me review learner submissions in ${course}. Ask to see one submission at a time, then draft feedback that names what is working before what is missing.`,
    });
  }

  actions.push(
    {
      id: "course-gaps",
      label: "Find the course's gaps",
      description: "Sequence, prerequisites, and pacing",
      prompt: `Inspect ${course} and tell me where the sequence, prerequisites, or pacing break down. Give me the single most important fix first, and ask before you change anything.`,
    },
    {
      id: "course-next",
      label: "Plan what comes next",
      description: "The next module or lesson",
      prompt: `Based on what is already in ${course}, propose the next module or lesson: its outcome, its practice, and why it belongs there. Wait for my changes before writing it into the course.`,
    },
  );

  return actions;
}

/** The palette's “ask Keating to search for X” hand-off. */
export function courseSearchAsk(
  query: string,
  context: Pick<CourseAskContext, "courseTitle" | "lessonTitle">,
): string {
  const where = context.lessonTitle
    ? ` I am on the lesson “${context.lessonTitle}”.`
    : "";
  return `I searched “${query}” inside my course “${context.courseTitle}” and did not find enough.${where} Search for it properly — in the course and on the web — and tell me what is worth adding, with links. Ask before changing the course.`;
}

export function truncateAsk(ask: string): string {
  return ask.length > MAX_ASK_LENGTH ? `${ask.slice(0, MAX_ASK_LENGTH - 1)}…` : ask;
}

/** Search params for a chat link that opens with the course loaded. */
export function courseChatSearch(
  courseId: string,
  ask?: string,
): { course: string; courseMode: "edit"; ask?: string } {
  return {
    course: courseId,
    courseMode: "edit",
    ...(ask ? { ask: truncateAsk(ask) } : {}),
  };
}

import { useEffect, useState } from "react";
import { Link } from "@tanstack/react-router";
import { ArrowUpRight, MessageSquareText, Sparkles } from "lucide-react";
import { css, cx } from "../../../styled-system/css";
import {
  courseAskActions,
  courseChatSearch,
  type CourseAskView,
} from "../../courses/course-ask";
import type { CourseLesson } from "../../courses/contracts";
import { courseLabelClass, formatCourseRelative } from "./course-ui";

interface CourseUpdatedDetail {
  courseId?: string;
  revision?: number;
  change?: string;
}

/**
 * Hand a specific request to Keating without losing the workspace. Links open
 * chat in a second tab, so edits Keating makes stream back into this view.
 */
export function CourseKeatingPanel({
  courseId,
  courseTitle,
  activeLesson,
  view,
}: {
  courseId: string;
  courseTitle: string;
  activeLesson?: CourseLesson;
  view: CourseAskView;
}) {
  const [lastChange, setLastChange] = useState<{
    change: string;
    at: string;
  } | null>(null);

  useEffect(() => {
    const onCourseUpdated = (event: Event) => {
      const detail = (event as CustomEvent<CourseUpdatedDetail>).detail;
      if (!detail || detail.courseId !== courseId || !detail.change) return;
      setLastChange({ change: detail.change, at: new Date().toISOString() });
    };
    window.addEventListener("keating:course-updated", onCourseUpdated);
    return () =>
      window.removeEventListener("keating:course-updated", onCourseUpdated);
  }, [courseId]);

  const actions = courseAskActions({
    courseTitle,
    ...(activeLesson
      ? { lessonTitle: activeLesson.title, lessonId: activeLesson.id }
      : {}),
    view,
  }).slice(0, 4);

  return (
    <section
      className={css({
        mt: "1.25rem",
        borderTop: "1px solid var(--ink)",
        pt: "1rem",
      })}
    >
      <div
        className={css({
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: "0.5rem",
        })}
      >
        <p className={courseLabelClass}>Work with Keating</p>
        <Sparkles size={14} />
      </div>
      <div className={css({ mt: "0.6rem", display: "grid", gap: "0.35rem" })}>
        {actions.map((action) => (
          <Link
            key={action.id}
            to="/chat"
            search={courseChatSearch(courseId, action.prompt)}
            target="_blank"
            rel="noreferrer"
            className={css({
              display: "grid",
              gridTemplateColumns: "minmax(0, 1fr) 0.9rem",
              alignItems: "center",
              gap: "0.4rem",
              border: "1px solid var(--ink)",
              bg: "var(--card)",
              px: "0.55rem",
              py: "0.45rem",
              color: "inherit",
              textDecoration: "none",
              _hover: { bg: "var(--course-wash, #ddebdd)" },
            })}
          >
            <span className={css({ minW: 0 })}>
              <strong className={css({ display: "block", fontSize: "0.76rem" })}>
                {action.label}
              </strong>
              <small
                className={css({
                  display: "block",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  whiteSpace: "nowrap",
                  fontSize: "0.66rem",
                  color: "var(--ink-soft)",
                })}
              >
                {action.description}
              </small>
            </span>
            <ArrowUpRight size={13} />
          </Link>
        ))}
      </div>
      <Link
        to="/chat"
        search={courseChatSearch(courseId)}
        className={cx(
          css({
            mt: "0.5rem",
            display: "inline-flex",
            alignItems: "center",
            gap: "0.35rem",
            fontSize: "0.72rem",
            fontWeight: 700,
            color: "inherit",
            textDecoration: "underline",
          }),
        )}
      >
        <MessageSquareText size={13} /> Open the full conversation
      </Link>
      {lastChange ? (
        <p
          className={css({
            mt: "0.6rem",
            borderLeft: "3px solid var(--course-green)",
            bg: "var(--course-wash, #ddebdd)",
            px: "0.5rem",
            py: "0.4rem",
            fontSize: "0.7rem",
            lineHeight: 1.45,
          })}
        >
          {lastChange.change}
          <small
            className={css({ display: "block", color: "var(--ink-soft)" })}
          >
            {formatCourseRelative(lastChange.at)} ago
          </small>
        </p>
      ) : null}
    </section>
  );
}

import { useMemo, useState } from "react";
import { ClipboardCheck, Users } from "lucide-react";
import { css, cx } from "../../../styled-system/css";
import {
  courseCompletionPercent,
  type CourseViewerSnapshot,
} from "../../courses/contracts";
import {
  courseButtonClass,
  courseEmptyClass,
  courseInputClass,
  courseLabelClass,
  coursePrimaryButtonClass,
  formatCourseRelative,
} from "./course-ui";

/** Teacher-side review: who is where, and what is waiting for feedback. */
export function CourseReviewPanel({
  snapshot,
  saving,
  onReview,
  onAssignmentReview,
  onRequestAccess,
}: {
  snapshot: CourseViewerSnapshot;
  saving: string;
  onReview(submissionId: string, feedback: string): void;
  onAssignmentReview(submissionId: string, feedback: string): void;
  onRequestAccess(accountId: string): void;
}) {
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [pendingOnly, setPendingOnly] = useState(true);
  const { course } = snapshot;

  const lessons = useMemo(
    () => course.modules.flatMap((module) => module.lessons),
    [course.modules],
  );
  const learners = course.members.filter(
    (member) => member.role === "student" || member.role === "peer",
  );
  const submissions = pendingOnly
    ? course.submissions.filter(
        (submission) => submission.review?.status !== "reviewed",
      )
    : course.submissions;
  const assignmentSubmissions = pendingOnly
    ? course.assignmentSubmissions.filter(
        (submission) => submission.review?.status !== "reviewed",
      )
    : course.assignmentSubmissions;

