          <strong>
            Your teacher requested full access to current and future course work.
          </strong>
          <button
            type="button"
            className={cx(s.button, s.primaryButton)}
            onClick={() =>
              void mutate(
                {
                  id: newCourseOperationId(),
                  courseId,
                  baseRevision: course.revision,
                  type: "teacher-access.respond",
                  approve: true,
                },
                "access",
              )
            }
          >
            Approve once
          </button>
          <button
            type="button"
            className={s.button}
            onClick={() =>
              void mutate(
                {
                  id: newCourseOperationId(),
                  courseId,
                  baseRevision: course.revision,
                  type: "teacher-access.respond",
                  approve: false,
                },
                "access",
              )
            }
          >
            Keep private
