          >
            <p className={s.sectionLabel}>Course outline</p>
            {permissions.canEditCourse ? (
              <button
                type="button"
                className={css({
                  fontSize: "0.65rem",
                  fontWeight: 700,
                  textDecoration: "underline",
                  cursor: "pointer",
                })}
                onClick={() => openBuilder("outline")}
              >
                edit
              </button>
            ) : null}
          </div>
          <div className={css({ mt: "0.75rem", display: "grid", gap: "1rem" })}>
            {course.modules.length ? (
              course.modules.map((module) => (
                <section key={module.id}>
                  <h2
                    className={css({
                      mb: "0.35rem",
                      fontSize: "0.75rem",
                      fontWeight: 800,
                      textTransform: "uppercase",
                      letterSpacing: "0.04em",
                    })}
                  >
                    {module.title}
                  </h2>
                  <div className={css({ display: "grid", gap: "0.25rem" })}>
                    {module.lessons.map((lesson, index) => {
                      const done = viewer.progress.completedLessonIds.includes(
                        lesson.id,
                      );
                      const threads = threadCounts[lesson.id] ?? 0;
                      return (
                        <button
                          key={lesson.id}
                          type="button"
                          onClick={() =>
                            selectLesson(
                              lesson.id,
                              view === "build" || view === "review"
                                ? view
                                : "read",
                            )
                          }
                          className={css({
                            display: "grid",
                            gridTemplateColumns: "1.4rem minmax(0, 1fr) auto",
                            alignItems: "center",
                            gap: "0.45rem",
                            borderLeft: "3px solid transparent",
                            px: "0.4rem",
                            py: "0.5rem",
                            textAlign: "left",
                            cursor: "pointer",
                            _hover: { bg: "var(--card)" },
                          })}
                          style={
                            activeLesson?.id === lesson.id
                              ? {
                                  background: "var(--card)",
                                  borderLeftColor: "var(--course-green)",
                                }
                              : undefined
                          }
                        >
                          <span
                            className={css({
                              display: "grid",
                              h: "1.25rem",
                              w: "1.25rem",
                              placeItems: "center",
                              borderRadius: "50%",
                              bg: done ? "var(--course-green)" : "transparent",
                              color: done ? "white" : "var(--ink-soft)",
                              fontSize: "0.7rem",
                            })}
                          >
                            {done ? <Check size={12} /> : index + 1}
                          </span>
                          <span
                            className={css({
                              fontSize: "0.78rem",
                              lineHeight: 1.35,
                            })}
                          >
                            {lesson.title}
                          </span>
                          {threads ? (
                            <span
                              className={courseCountChipClass}
                              title={`${threads} comments`}
                            >
                              {threads}
                            </span>
                          ) : null}
                        </button>
                      );
                    })}
                    {module.lessons.length ? null : (
                      <p
                        className={css({
                          fontSize: "0.72rem",
                          color: "var(--ink-soft)",
                        })}
                      >
                        No lessons yet
                      </p>
                    )}
                  </div>
                </section>
              ))
            ) : (
              <p className={courseEmptyClass}>
                No modules yet. A blank course is valid — add the outline when it
                is clear.
              </p>
            )}
          </div>

          <div
            className={css({
              mt: "1.25rem",
              display: "grid",
              gap: "0.15rem",
              borderTop: "1px solid var(--ink)",
              pt: "0.85rem",
            })}
          >
            <p className={cx(s.sectionLabel, css({ mb: "0.35rem" }))}>
              Course shelf
            </p>
            <ShelfRow
              icon={FileText}
              label="Documents"
              count={course.materials.length}
              onClick={
                permissions.canEditCourse
                  ? () => openBuilder("documents")
                  : undefined
              }
            />
            <ShelfRow
              icon={BookUp}
              label="Assignments"
              count={course.assignments.length}
              onClick={
                permissions.canEditCourse
                  ? () => openBuilder("assignments")
                  : undefined
              }
            />
            <ShelfRow
              icon={Shapes}
              label="Artifacts"
              count={course.artifacts.length}
              onClick={
                permissions.canEditCourse
                  ? () => openBuilder("artifacts")
                  : undefined
              }
            />
            <ShelfRow
              icon={CreditCard}
              label="Cards"
              count={course.cards.length}
              onClick={
                permissions.canEditDeck ? () => openBuilder("cards") : undefined
              }
            />
            <ShelfRow
              icon={MessageSquareText}
              label="Course thread"
              count={threadCounts.course ?? 0}
              onClick={() => {
                dispatch({ type: "discuss.channel", channel: COURSE_CHANNEL });
                dispatch({ type: "view.changed", view: "discuss" });
              }}
            />
          </div>
        </aside>

        <main className={s.center}>
          {view === "read" ? (
            <DeskView
              snapshot={snapshot}
              {...(activeLesson ? { lesson: activeLesson } : {})}
              moduleTitle={activeModule?.title ?? "Course"}
              completed={completed}
              mutate={mutate}
              saving={saving}
              noteText={noteText}
              setNoteText={(value) =>
                dispatch({ type: "note.changed", value })
              }
              sharedNoteVersion={sharedNote?.version ?? 0}
              answer={answer}
              setAnswer={(value) => dispatch({ type: "answer.changed", value })}
              shareAnswer={shareAnswer}
              setShareAnswer={(value) =>
                dispatch({ type: "share-answer.changed", value })
              }
              threadCount={
                activeLesson ? (threadCounts[activeLesson.id] ?? 0) : 0
              }
              onSnapshot={setSnapshot}
              onError={setError}
              onToggleReaction={toggleReaction}
              onOpenBuilder={openBuilder}
              onDiscuss={() =>
                dispatch({ type: "view.changed", view: "discuss" })
              }
              onComplete={() =>
                activeLesson &&
                void mutate(
                  {
                    id: newCourseOperationId(),
                    courseId,
                    baseRevision: course.revision,
                    type: "lesson.complete",
                    lessonId: activeLesson.id,
                    completed: !completed,
                  },
                  "complete",
                )
              }
              onSaveNote={() =>
                activeLesson &&
                void mutate(
                  {
                    id: newCourseOperationId(),
                    courseId,
                    baseRevision: course.revision,
                    type: "shared-note.update",
                    noteId: sharedNote?.id ?? `note_${activeLesson.id}`,
                    lessonId: activeLesson.id,
                    title: `${activeLesson.title} notes`,
                    text: noteText,
                    baseVersion: sharedNote?.version ?? 0,
                  },
                  "note",
                )
              }
              onSaveAnswer={() =>
                activeLesson?.exercise &&
                void mutate(
                  {
                    id: newCourseOperationId(),
                    courseId,
                    baseRevision: course.revision,
                    type: "submission.save",
                    submissionId:
                      ownSubmission?.id ??
                      `submission_${crypto.randomUUID().replaceAll("-", "")}`,
                    lessonId: activeLesson.id,
                    exerciseId: activeLesson.exercise.id,
                    answer,
                    sharedWithPeers: shareAnswer,
                  },
                  "answer",
                )
              }
            />
          ) : null}
          {view === "discuss" ? (
            <CourseDiscussion
              snapshot={snapshot}
              channel={discussChannel}
              onChannelChange={(channel) =>
                dispatch({ type: "discuss.channel", channel })
              }
              saving={saving}
              mutate={mutate}
              onSelectLesson={(lessonId) => selectLesson(lessonId, "discuss")}
            />
          ) : null}
          {view === "review" && permissions.canReview ? (
            <CourseReviewPanel
              snapshot={snapshot}
              saving={saving}
              onReview={(submissionId, feedback) =>
                void mutate(
                  {
                    id: newCourseOperationId(),
                    courseId,
                    baseRevision: course.revision,
                    type: "submission.review",
                    submissionId,
                    status: "reviewed",
                    feedback,
                  },
                  "review",
                )
              }
              onAssignmentReview={(submissionId, feedback) =>
                void mutate(
                  {
                    id: newCourseOperationId(),
                    courseId,
                    baseRevision: course.revision,
                    type: "assignment.submission.review",
                    submissionId,
                    status: "reviewed",
                    feedback,
                  },
                  "assignment-review",
                )
              }
              onRequestAccess={(accountId) =>
                void mutate(
                  {
                    id: newCourseOperationId(),
                    courseId,
                    baseRevision: course.revision,
                    type: "teacher-access.request",
                    memberAccountId: accountId,
                  },
                  "access",
                )
              }
            />
          ) : null}
          {view === "build" && canBuild ? (
            <CourseBuilder
              snapshot={snapshot}
              {...(activeLesson ? { activeLesson } : {})}
              section={builderSection}
              saving={saving}
              onSectionChange={openBuilder}
              mutate={mutate}
              onSnapshot={setSnapshot}
              onSelectLesson={(lessonId) => selectLesson(lessonId)}
              onInvite={() => dispatch({ type: "invite.changed", open: true })}
              onError={setError}
            />
          ) : null}
        </main>

        <aside className={s.right}>
          <p className={s.sectionLabel}>Live room</p>
          <div className={css({ mt: "0.6rem", display: "grid", gap: "0.5rem" })}>
            {course.members.map((member) => (
              <div
                key={member.accountId}
                className={css({
                  display: "flex",
                  alignItems: "center",
                  gap: "0.55rem",
                  fontSize: "0.78rem",
                })}
              >
                <span
                  className={css({
                    position: "relative",
                    display: "grid",
                    h: "1.75rem",
                    w: "1.75rem",
                    placeItems: "center",
                    borderRadius: "50%",
                    bg:
                      member.role === "teacher" || member.role === "owner"
                        ? "var(--course-green)"
                        : "var(--peer-blue, #3468b3)",
                    fontWeight: 800,
                    color: "white",
                  })}
                >
                  {member.displayName.charAt(0).toUpperCase()}
                  <span
                    className={css({
                      position: "absolute",
                      right: "-1px",
                      bottom: "-1px",
                      h: "0.5rem",
                      w: "0.5rem",
                      border: "1px solid var(--paper-deep)",
                      borderRadius: "50%",
                      bg: online.has(member.accountId)
                        ? "var(--phosphor, #4be388)"
                        : "#9ba19a",
                    })}
                  />
                </span>
                <span className={css({ minW: 0, flex: 1 })}>
                  <strong
                    className={css({
                      display: "block",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    })}
                  >
                    {memberName(member, viewer.accountId)}
                  </strong>
                  <span
                    className={css({
                      fontSize: "0.67rem",
                      color: "var(--ink-soft)",
                      textTransform: "uppercase",
                    })}
                  >
                    {member.role}
                  </span>
                </span>
              </div>
            ))}
          </div>
          <section
            className={css({
              mt: "1.25rem",
              borderTop: "1px solid var(--ink)",
              pt: "1rem",
            })}
          >
            <p className={s.sectionLabel}>Progress</p>
            <div
              className={css({
                mt: "0.6rem",
                h: "0.5rem",
                overflow: "hidden",
                border: "1px solid var(--ink)",
                bg: "var(--paper)",
              })}
            >
              <div
                style={{ width: `${courseCompletionPercent(course, viewer)}%` }}
                className={css({ h: "100%", bg: "var(--course-green)" })}
              />
            </div>
            <p
              className={css({
                mt: "0.35rem",
                fontFamily: "var(--mono-display)",
                fontSize: "0.67rem",
              })}
            >
              {courseCompletionPercent(course, viewer)}% complete
            </p>
          </section>
          <CourseKeatingPanel
            courseId={course.id}
            courseTitle={course.title}
            {...(activeLesson ? { activeLesson } : {})}
            view={view}
          />
          <section
            className={css({
              mt: "1.25rem",
              borderTop: "1px solid var(--ink)",
              pt: "1rem",
            })}
          >
            <p className={s.sectionLabel}>Recent activity</p>
            <div className={css({ mt: "0.6rem", display: "grid", gap: "0.65rem" })}>
              {course.activity.length ? (
                course.activity.slice(0, 6).map((item) => (
                  <div
                    key={item.id}
                    className={css({
                      display: "grid",
                      gridTemplateColumns: "0.5rem minmax(0, 1fr)",
                      gap: "0.5rem",
                      fontSize: "0.72rem",
                    })}
                  >
                    <span
                      className={css({
                        mt: "0.3rem",
                        h: "0.4rem",
                        w: "0.4rem",
                        borderRadius: "50%",
                        bg: "var(--course-green)",
                      })}
                    />
                    <span>
                      {item.message}
                      <small
                        className={css({
                          display: "block",
                          color: "var(--ink-soft)",
                        })}
                      >
                        {formatCourseRelative(item.createdAt)}
                      </small>
                    </span>
                  </div>
                ))
              ) : (
                <p className={css({ fontSize: "0.72rem", color: "var(--ink-soft)" })}>
                  Nothing has happened here yet.
                </p>
              )}
            </div>
          </section>
          {snapshot.network?.publicKey && (
            <details
              className={css({
                mt: "1rem",
                borderTop: "1px solid var(--ink)",
                pt: "0.75rem",
              })}
            >
              <summary
                className={css({
                  cursor: "pointer",
                  fontFamily: "var(--mono-display)",
                  fontSize: "0.65rem",
                  fontWeight: 700,
                  textTransform: "uppercase",
                })}
              >
                Pear feed
              </summary>
              <p
                className={css({
                  mt: "0.5rem",
                  overflowWrap: "anywhere",
                  fontFamily: "var(--mono-body)",
                  fontSize: "0.6rem",
                  color: "var(--ink-soft)",
                })}
              >
                {snapshot.network.publicKey}
              </p>
            </details>
          )}
        </aside>
      </div>
      {inviteOpen && (
        <CourseInviteDialog
          courseId={courseId}
          onClose={() => dispatch({ type: "invite.changed", open: false })}
        />
      )}
      {paletteOpen && (
        <CourseCommandPalette
          course={course}
          onClose={() => dispatch({ type: "palette.changed", open: false })}
          onSelect={openSearchResult}
          onAskKeating={(query) => {
            dispatch({ type: "palette.changed", open: false });
            askKeating(
              courseSearchAsk(query, {
                courseTitle: course.title,
                ...(activeLesson ? { lessonTitle: activeLesson.title } : {}),
              }),
            );
          }}
        />
      )}
    </div>
  );
}

function ShelfRow({
  icon: Icon,
  label,
  count,
  onClick,
}: {
  icon: typeof FileText;
  label: string;
  count: number;
  onClick?: () => void;
}) {
  const body = (
    <>
      <span
        className={css({
          display: "inline-flex",
          alignItems: "center",
          gap: "0.4rem",
          fontSize: "0.76rem",
          fontWeight: 650,
        })}
      >
        <Icon size={14} /> {label}
