            <FileText size={15} />
          )}
          <span>
            <strong className={css({ display: "block", fontSize: "0.8rem" })}>
              {material.title}
            </strong>
            <small className={css({ color: "var(--ink-soft)" })}>
              {material.fileName ?? material.url ?? "Course document"}
            </small>
          </span>
        </span>
        <ExternalLink size={14} />
