import { defineConfig } from "@pandacss/dev";

const fonts = {
  monoDisplay: '"Space Mono", ui-monospace, "Cascadia Mono", Menlo, monospace',
  monoBody: '"JetBrains Mono", ui-monospace, "Cascadia Mono", Menlo, monospace',
